import{_ as e,o as t,c as i,ai as r}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Python 面试 · 并发与 IO","description":"","frontmatter":{},"headers":[],"relativePath":"guide/python/async-io-interview.md","filePath":"guide/python/async-io-interview.md"}'),l={name:"guide/python/async-io-interview.md"};function n(s,a,d,h,o,c){return t(),i("div",null,[...a[0]||(a[0]=[r(`<h1 id="python-面试-·-并发与-io" tabindex="-1">Python 面试 · 并发与 IO <a class="header-anchor" href="#python-面试-·-并发与-io" aria-label="Permalink to “Python 面试 · 并发与 IO”">​</a></h1><hr><h2 id="高频问法" tabindex="-1">高频问法 <a class="header-anchor" href="#高频问法" aria-label="Permalink to “高频问法”">​</a></h2><ol><li>多线程、多进程、asyncio 怎么选？</li><li>调 HTTP API 要注意什么？</li><li>如何读大文件 / 流式处理？</li><li>异常与重试策略？</li><li>日志怎么打？</li><li>和 Java 线程池比，你怎么理解？</li></ol><hr><h2 id="口述参考" tabindex="-1">口述参考 <a class="header-anchor" href="#口述参考" aria-label="Permalink to “口述参考”">​</a></h2><h3 id="_1-选型表" tabindex="-1">1）选型表 <a class="header-anchor" href="#_1-选型表" aria-label="Permalink to “1）选型表”">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>更合适</th><th>原因</th></tr></thead><tbody><tr><td>等网络/磁盘</td><td>多线程或 asyncio</td><td>IO 等待可重叠</td></tr><tr><td>重 CPU</td><td>多进程</td><td>绕过 GIL 吃多核</td></tr><tr><td>大量并发连接</td><td>asyncio</td><td>单线程协程，注意别阻塞</td></tr><tr><td>简单脚本偶尔并行</td><td>concurrent.futures</td><td>API 简单</td></tr></tbody></table><p>注意：asyncio 里调用同步阻塞（重计算、同步 requests）会堵整个循环——要用线程池包一层或换异步库。</p><h3 id="_2-http-调用清单" tabindex="-1">2）HTTP 调用清单 <a class="header-anchor" href="#_2-http-调用清单" aria-label="Permalink to “2）HTTP 调用清单”">​</a></h3><ul><li><strong>timeout</strong>（连接 + 读取）必设</li><li>状态码与业务 code 分开处理</li><li>重试：仅幂等（GET/部分 PUT）；加退避</li><li>连接池：<code>requests.Session</code> / httpx</li><li>密钥：环境变量或密钥管理，不进仓库</li><li>日志：打 URL/耗时/状态，脱敏 Token</li></ul><p>调 AI API 同理：超时、重试、限流、费用与失败原因可观测——见 <a href="/my-vitepress-site/ai/dev/basics/ai-app-min-loop.html">AI 应用最小链路</a>。</p><h3 id="_3-大文件" tabindex="-1">3）大文件 <a class="header-anchor" href="#_3-大文件" aria-label="Permalink to “3）大文件”">​</a></h3><p>逐行 / 分块读；生成器管道；别 <code>read()</code> 一次性进内存。<br> CSV/日志处理是面试常场景。</p><h3 id="_4-异常与重试" tabindex="-1">4）异常与重试 <a class="header-anchor" href="#_4-异常与重试" aria-label="Permalink to “4）异常与重试”">​</a></h3><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>可重试：超时、429、5xx（看业务）</span></span>
<span class="line"><span>不可盲重试：4xx 参数错误、业务拒绝、非幂等写</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>捕获具体异常；记录上下文；最终失败要有明确返回或告警。</p><h3 id="_5-日志" tabindex="-1">5）日志 <a class="header-anchor" href="#_5-日志" aria-label="Permalink to “5）日志”">​</a></h3><p>用 <code>logging</code> 模块；级别区分；脚本也要有格式（时间、级别、消息）。<br> 生产避免 <code>print</code> 当日志。</p><h3 id="_6-对比-java" tabindex="-1">6）对比 Java <a class="header-anchor" href="#_6-对比-java" aria-label="Permalink to “6）对比 Java”">​</a></h3><p>Java 业务里常用线程池、边界清晰；Python 脚本侧更常「按任务选模型」。<br> 你可说：主系统 Java；辅助链路 Python，契约用 HTTP/文件/消息对齐。</p><hr><h2 id="追问预备" tabindex="-1">追问预备 <a class="header-anchor" href="#追问预备" aria-label="Permalink to “追问预备”">​</a></h2><ul><li>「GIL 下线程还有用吗？」→ IO 密集有用；CPU 密集有限。</li><li>「如何优雅停？」→ 捕获信号、设 stop flag、线程/进程可 join、关闭连接。</li></ul>`,24)])])}const _=e(l,[["render",n]]);export{b as __pageData,_ as default};
